SELECT * FROM ( WITH source_data AS ( SELECT h.modified_hist_seq, h.tbl_seq, h.before_value, h.after_value, h.modified_content, h.note, h.office_seq, h.create_at, h.create_user, u.user_name_ko AS actionUser FROM utb_modified_hist h LEFT JOIN utb_user_info u ON h.create_user = u.user_info_seq WHERE h.office_seq = #{request.officeSeq} AND h.del_yn = 'N'
AND h.tbl_seq = #{request.tblSeq}
), mapped_data AS ( SELECT s.*, COALESCE( app_dir.app_seq, cft.app_seq, req.app_seq, ids.app_seq, CASE WHEN (s.tbl_seq LIKE 'APPMST%') THEN s.tbl_seq WHEN (s.tbl_seq LIKE 'CFTMST%') THEN cft.app_seq ELSE NULL END ) AS resolved_app_seq, cft.case_classification AS cft_route, cft.case_category_code AS cft_category FROM source_data s LEFT JOIN "MP_IPMS_PA".utb_app_mst app_dir ON s.tbl_seq = app_dir.app_seq AND s.office_seq = app_dir.office_seq LEFT JOIN "MP_IPMS_PA".utb_conflict_mst cft ON s.tbl_seq = cft.conflict_seq AND s.office_seq = cft.office_seq LEFT JOIN "MP_IPMS_PA".utb_required_document req ON s.tbl_seq = req.required_doc_seq AND s.office_seq = req.office_seq LEFT JOIN "MP_IPMS_PA".utb_app_ids ids ON s.tbl_seq = ids.ids_seq AND s.office_seq = ids.office_seq ) SELECT m.modified_hist_seq AS "seq", to_char(m.create_at, 'YYYY-MM-DD HH:MI:SS') AS "actionDateTime", m.modified_content AS "actionType", COALESCE(m.cft_category, app.app_classification) AS "caseCategoryCode", "MP_IPMS_PA".fn_get_cd_nm('NAT_IO_DIV', COALESCE(m.cft_category, app.app_classification)) AS "caseCategory", COALESCE(app.asset_no) AS "ourRef", COALESCE(app.app_no, '') AS "appNo", COALESCE(app.reg_no, '') AS "regNo", m.note AS "fieldName", m.before_value AS "beforeValue", m.after_value AS "afterValue", m.actionUser AS "actionUser", app.dept_code AS "deptName", m.create_at FROM mapped_data m LEFT JOIN "MP_IPMS_PA".utb_app_mst app ON m.resolved_app_seq = app.app_seq AND m.office_seq = app.office_seq ) Z WHERE 1=1
ORDER BY Z.create_at DESC
LIMIT #{request.pageSize} OFFSET #{request.offSet}

SELECT COUNT(*) FROM ( WITH source_data AS ( SELECT h.modified_hist_seq, h.tbl_seq, h.before_value, h.after_value, h.modified_content, h.note, h.office_seq, h.create_at, h.create_user, u.user_name_ko AS actionUser FROM utb_modified_hist h LEFT JOIN utb_user_info u ON h.create_user = u.user_info_seq WHERE h.office_seq = #{request.officeSeq} AND h.del_yn = 'N'
AND h.tbl_seq = #{request.tblSeq}
), mapped_data AS ( SELECT s.*, COALESCE( app_dir.app_seq, cft.app_seq, req.app_seq, ids.app_seq, CASE WHEN (s.tbl_seq LIKE 'APPMST%') THEN s.tbl_seq WHEN (s.tbl_seq LIKE 'CFTMST%') THEN cft.app_seq ELSE NULL END ) AS resolved_app_seq, cft.case_classification AS cft_route, cft.case_category_code AS cft_category FROM source_data s LEFT JOIN "MP_IPMS_PA".utb_app_mst app_dir ON s.tbl_seq = app_dir.app_seq AND s.office_seq = app_dir.office_seq LEFT JOIN "MP_IPMS_PA".utb_conflict_mst cft ON s.tbl_seq = cft.conflict_seq AND s.office_seq = cft.office_seq LEFT JOIN "MP_IPMS_PA".utb_required_document req ON s.tbl_seq = req.required_doc_seq AND s.office_seq = req.office_seq LEFT JOIN "MP_IPMS_PA".utb_app_ids ids ON s.tbl_seq = ids.ids_seq AND s.office_seq = ids.office_seq ) SELECT m.modified_hist_seq AS "seq", to_char(m.create_at, 'YYYY-MM-DD HH:MI:SS') AS "actionDateTime", m.modified_content AS "actionType", COALESCE(m.cft_category, app.app_classification) AS "caseCategoryCode", "MP_IPMS_PA".fn_get_cd_nm('NAT_IO_DIV', COALESCE(m.cft_category, app.app_classification)) AS "caseCategory", COALESCE(app.asset_no) AS "ourRef", COALESCE(app.app_no, '') AS "appNo", COALESCE(app.reg_no, '') AS "regNo", m.note AS "fieldName", m.before_value AS "beforeValue", m.after_value AS "afterValue", m.actionUser AS "actionUser", app.dept_code AS "deptName", m.create_at FROM mapped_data m LEFT JOIN "MP_IPMS_PA".utb_app_mst app ON m.resolved_app_seq = app.app_seq AND m.office_seq = app.office_seq ) Z WHERE 1=1

